      "Landslides": "\u0BA8\u0BBF\u0BB2\u0B9A\u0BCD\u0B9A\u0BB0\u0BBF\u0BB5\u0BC1\u0B95\u0BB3\u0BCD",
      "Flash Floods": "\u0BA4\u0BBF\u0B9F\u0BC0\u0BB0\u0BCD \u0BB5\u0BC6\u0BB3\u0BCD\u0BB3\u0BAE\u0BCD",
