      "ARAVINDHA ENGINE": "\u0B85\u0BB0\u0BB5\u0BBF\u0BA8\u0BCD\u0BA4\u0BBE \u0B8E\u0B9E\u0BCD\u0B9A\u0BBF\u0BA9\u0BCD",
      "Landslide Risk": "\u0BA8\u0BBF\u0BB2\u0B9A\u0BCD\u0B9A\u0BB0\u0BBF\u0BB5\u0BC1 \u0B85\u0BAA\u0BBE\u0BAF\u0BAE\u0BCD",
      "REGIONAL RISK ANALYTICS": "\u0BAA\u0BBF\u0BB0\u0BBE\u0BA8\u0BCD\u0BA4\u0BBF\u0BAF \u0B85\u0BAA\u0BBE\u0BAF \u0BAA\u0B95\u0BC1\u0BAA\u0BCD\u0BAA\u0BBE\u0BAF\u0BCD\u0BB5\u0BC1",
