      "Monthly Landslide Events": "\u0BAE\u0BBE\u0BA4\u0BBE\u0BA8\u0BCD\u0BA4\u0BBF\u0BB0 \u0BA8\u0BBF\u0BB2\u0B9A\u0BCD\u0B9A\u0BB0\u0BBF\u0BB5\u0BC1 \u0BA8\u0BBF\u0B95\u0BB4\u0BCD\u0BB5\u0BC1\u0B95\u0BB3\u0BCD",
      "Road & Evacuation Corridors": "\u0B9A\u0BBE\u0BB2\u0BC8 \u0BAE\u0BB1\u0BCD\u0BB1\u0BC1\u0BAE\u0BCD \u0BB5\u0BC6\u0BB3\u0BBF\u0BAF\u0BC7\u0BB1\u0BCD\u0BB1 \u0BAA\u0BBE\u0BA4\u0BC8\u0B95\u0BB3\u0BCD",
      "Yearly": "\u0B86\u0BA3\u0BCD\u0B9F\u0BC1\u0BA4\u0BCB\u0BB1\u0BC1\u0BAE\u0BCD",
      "Monthly": "\u0BAE\u0BBE\u0BA4\u0BBE\u0BA8\u0BCD\u0BA4\u0BBF\u0BB0\u0BAE\u0BCD",
