  // src/modules/ml-client.js
  var ortSessionPromise = null;
  var onnxBroken = false;
  var FEATURES = [
    "rain_1d",
    "rain_3d",
    "rain_7d",
    "rain_15d",
    "rain_max_7d",
    "elevation_m",
    "slope_deg",
    "month_sin",
    "month_cos"
  ];
  function monthFeatures(month) {
    const m2 = month && month >= 1 && month <= 12 ? month : (/* @__PURE__ */ new Date()).getMonth() + 1;
    return { month_sin: Math.sin(2 * Math.PI * m2 / 12), month_cos: Math.cos(2 * Math.PI * m2 / 12) };
  }
  function quickHeuristic(f2) {
    const sat = Math.max(0, Math.min(1, (f2.rain_15d || 0) / 900));
    const burst = Math.max(0, Math.min(1, (f2.rain_1d || 0) / 350));
    const slopeT = Math.max(0, Math.min(1, Math.max(0, (f2.slope_deg ?? 15) - 8) / 50));
    const z2 = -4.2 + 2.6 * sat + 2.2 * burst + 1.9 * slopeT;
    return 1 / (1 + Math.exp(-z2));
  }
  async function getOrt() {
    if (onnxBroken) return null;
    if (!ortSessionPromise) {
      ortSessionPromise = (async () => {
        try {
          const ort = await Promise.resolve().then(() => (init_ort_bundle_min(), ort_bundle_min_exports));
          ort.env.wasm.numThreads = 1;
          ort.env.wasm.wasmPaths = new URL("ort/", document.baseURI).href;
          return await ort.InferenceSession.create("model.onnx", {
            executionProviders: ["wasm"],
            graphOptimizationLevel: "all"
          });
        } catch (e64) {
          console.warn("[ML] ONNX unavailable, using API/heuristic fallback:", e64?.message);
          onnxBroken = true;
          return null;
        }
      })();
    }
    return ortSessionPromise;
  }
  async function predictLandslideProbability(features) {
    const f2 = {
      rain_1d: features.rain_1d ?? 0,
      rain_3d: features.rain_3d ?? (features.rain_1d ?? 0) * 2.2,
      rain_7d: features.rain_7d ?? (features.rain_1d ?? 0) * 3.6,
      rain_15d: features.rain_15d ?? (features.rain_1d ?? 0) * 5,
      rain_max_7d: features.rain_max_7d ?? features.rain_1d ?? 0,
      elevation_m: features.elevation_m ?? features.elevation ?? 500,
      slope_deg: features.slope_deg ?? features.slope ?? 15,
      ...monthFeatures(features.month)
    };
    try {
      const ort = await Promise.resolve().then(() => (init_ort_bundle_min(), ort_bundle_min_exports));
      const session = await getOrt();
      if (session) {
        const input = new ort.Tensor(
          "float32",
          Float32Array.from(FEATURES.map((k3) => f2[k3])),
          [1, FEATURES.length]
        );
        const res = await session.run({ input });
        const probsName = session.outputNames.find((n2) => {
          const t5 = res[n2];
          return t5 && t5.type === "float32" && t5.data && t5.data.length >= 1;
        }) || session.outputNames[session.outputNames.length - 1];
        const t4 = res[probsName];
        const prob = t4.data.length === 1 ? t4.data[0] : t4.data[t4.data.length - 1];
        if (!Number.isFinite(prob)) throw new Error("ONNX returned non-finite probability");
        return { probability: prob, source: "onnx-browser", model: "GBDT real-data (browser)" };
      }
    } catch (e64) {
      console.warn("[ML] ONNX inference unavailable this call, using API/heuristic fallback:", e64?.message || e64);
      onnxBroken = true;
      ortSessionPromise = null;
    }
    try {
      const res = await fetch("http://localhost:8000/predict", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(f2),
        signal: AbortSignal.timeout(2500)
      });
      if (res.ok) {
        const j3 = await res.json();
        return { probability: j3.probability, source: "fastapi", model: j3.model_version };
      }
    } catch {
    }
    return {
      probability: quickHeuristic(f2),
      source: "heuristic",
      model: "logistic-antecedent-v1"
    };
  }
  async function predictRiskLevel(features) {
    const r2 = await predictLandslideProbability(features);
    const score = Math.round(Math.max(0, Math.min(100, r2.probability * 100)));
    const level = score >= 75 ? "SEVERE" : score >= 50 ? "HIGH" : score >= 25 ? "MODERATE" : "LOW";
    return { ...r2, riskScore: score, riskLevel: level };
  }

  // src/modules/analytics.js
  var ML_API = "http://localhost:8000";
  function initAnalytics() {
    fetchLatestMLPredictions();
    setInterval(fetchLatestMLPredictions, 6e4);
    fetchModelInfo();
  }
  async function fetchModelInfo() {
    try {
      const res = await fetch(`${ML_API}/model-info`, { signal: AbortSignal.timeout(2500) });
      if (!res.ok) return null;
      const meta = await res.json();
      const badge = document.getElementById("mlModelBadge");
      if (badge && meta.auc_roc) {
        const data = meta.trained_on_real_data ? "real COOLR inventory" : "synthetic data";
        badge.innerHTML = `\u{1F916} GBDT \xB7 ${data} \xB7 ${meta.positives}+/${meta.negatives}\u2212 \xB7 AUC ${meta.auc_roc} \xB7 ${meta.model_version}`;
        badge.title = `Trained: ${meta.rows} samples, test AUC-ROC ${meta.auc_roc}, Brier ${meta.brier}. Features: ${(meta.features || []).join(", ")}`;
      }
      return meta;
    } catch {
      return null;
    }
  }
  async function fetchLatestMLPredictions() {
    try {
      const result = await predictRiskLevel({
        rain_1d: 128,
        rain_3d: 282,
        rain_7d: 461,
        rain_15d: 640,
        rain_max_7d: 128,
        elevation_m: 1650,
        slope_deg: 34
      });
      updateMLRiskCards({
        risk_level: result.riskLevel,
        risk_score: result.riskScore,
        confidence: Math.max(0.5, Math.abs(result.probability - 0.5) * 2),
        factors: [],
        _source: result.source
      });
    } catch (err) {
      console.warn("[Analytics Module] ML prediction unavailable:", err.message);
    }
  }
  function updateMLRiskCards(latestPrediction) {
    const riskStatusValue = document.querySelector("#riskStatusValue");
    const riskStatusText = document.querySelector("#riskStatusText");
    if (riskStatusValue) {
      riskStatusValue.textContent = latestPrediction.risk_level || "MONITORING";
      riskStatusValue.style.color = getLevelColor(latestPrediction.risk_level);
    }
    if (riskStatusText) {
      riskStatusText.textContent = `AI/ML Model Confidence: ${(latestPrediction.confidence * 100).toFixed(0)}%`;
    }
    const scoreElement = document.querySelector("#landslideRiskScore");
    const levelElement = document.querySelector("#landslideRiskLevel");
    if (scoreElement) {
      scoreElement.textContent = `${latestPrediction.risk_score}`;
    }
    if (levelElement) {
      levelElement.textContent = `${latestPrediction.risk_level} (ML)`;
    }
    const messageElement = document.querySelector("#riskMessage");
    if (messageElement) {
      const src = latestPrediction._source;
      messageElement.textContent = src === "onnx-browser" ? "Gradient Boosting Model (trained on NASA COOLR landslide inventory) scoring live in your browser." : src === "fastapi" ? "Gradient Boosting Model (trained on NASA COOLR landslide inventory) via FastAPI service." : "Running calibrated local heuristic \u2014 start the ML service for full model inference.";
    }
    renderMLContributingFactors(latestPrediction);
  }
  function renderMLContributingFactors(latestPrediction) {
    const riskFactorsBox = document.querySelector(".risk-factors");
    if (!riskFactorsBox) return;
    let mlBadge = document.getElementById("mlModelBadge");
    if (!mlBadge) {
      mlBadge = document.createElement("div");
      mlBadge.id = "mlModelBadge";
      mlBadge.className = "ml-badge";
      mlBadge.innerHTML = "\u{1F916} Powered by Real-Data GBDT (NASA COOLR + Open-Meteo)";
      riskFactorsBox.parentNode.insertBefore(mlBadge, riskFactorsBox);
    }
  }
  function getLevelColor(level) {
    switch (level) {
      case "SEVERE":
        return "#ff0055";
      case "HIGH":
        return "#ff9900";
      case "MODERATE":
        return "#ffcc00";
      default:
        return "#38b000";
    }
  }

  // src/modules/sensors.js
  var socket = null;
  function initSensorsWebSocket() {
    const wsUrl = window.location.origin.includes("localhost") || window.location.origin.includes("127.0.0.1") ? "http://localhost:4000" : window.location.origin;
    if (typeof window.io === "undefined") {
      const script = document.createElement("script");
      script.src = "https://cdn.socket.io/4.7.5/socket.io.min.js";
      script.onload = () => connectSocket(wsUrl);
      document.head.appendChild(script);
    } else {
      connectSocket(wsUrl);
    }
  }
  function connectSocket(wsUrl) {
    try {
      socket = window.io(wsUrl, { reconnectionAttempts: 5, timeout: 5e3 });
      socket.on("connect", () => {
        console.log("\u{1F4E1} Connected to ARAVINDHA Socket.IO Realtime Gateway");
        updateSystemOnlineIndicator(true);
      });
      socket.on("disconnect", () => {
        console.warn("\u26A0\uFE0F Realtime WebSocket disconnected");
        updateSystemOnlineIndicator(false);
      });
      socket.on("new_field_report", (report) => {
        console.log("\u26A1 Live Field Report received:", report);
        fetchAndRenderFieldReports();
        showToastNotification(`New Field Report: ${report.title}`, report.hazard_type);
      });
      socket.on("risk_update", (data) => {
        console.log("\u26A1 Risk Update received:", data);
        fetchLatestMLPredictions();
      });
      socket.on("system_alert", (alert2) => {
        console.warn("\u{1F6A8} SYSTEM ALERT:", alert2);
        showToastNotification(`\u{1F6A8} ${alert2.title}`, alert2.message);
        fetchAndRenderAlertHistory();
      });
      socket.on("sensor_reading", (reading) => {
        updateSensorWidgetUI(reading);
      });
    } catch (err) {
      console.warn("[WebSocket Init Error]", err.message);
    }
  }
  function updateSystemOnlineIndicator(isOnline) {
    const dots = document.querySelectorAll(".status-dot");
    dots.forEach((d2) => {
      d2.style.backgroundColor = isOnline ? "#38b000" : "#ff4d6d";
    });
  }
  function updateSensorWidgetUI(reading) {
    if (reading.type === "soil_moisture") {
      const soilVal = document.querySelector("#soilMoistureValue");
      if (soilVal) soilVal.textContent = `${reading.value}%`;
    }
  }
  function showToastNotification(title, body) {
    const toast = document.createElement("div");
    toast.className = "live-toast";
    toast.innerHTML = `
    <strong>${title}</strong>
    <p>${body}</p>
  `;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4500);
  }

