    /**
     * Topographic Contour Lines
     */
    setupContourOverlay() {
      if (!this.map) return;
      const preset = this.getCurrentPreset();
      const [cLon, cLat] = preset.center;
      const contourFeatures = [
        { elev: 1e3, r: 0.024, label: "1000 m" },
        { elev: 1200, r: 0.019, label: "1200 m" },
        { elev: 1400, r: 0.014, label: "1400 m" },
        { elev: 1600, r: 9e-3, label: "1600 m" },
        { elev: 1800, r: 4e-3, label: "1800 m" }
      ].map((item) => {
        const ring = [];
        const numPts = 32;
        for (let i2 = 0; i2 <= numPts; i2++) {
          const a2 = i2 / numPts * Math.PI * 2;
          const warp = 1 + 0.25 * Math.sin(a2 * 3) + 0.15 * Math.cos(a2 * 5);
          const lon = cLon + Math.cos(a2) * item.r * warp * 1.3;
          const lat = cLat + Math.sin(a2) * item.r * warp * 0.8;
          ring.push([lon, lat]);
        }
        return {
          type: "Feature",
          properties: { elevation: item.elev, label: item.label },
          geometry: { type: "LineString", coordinates: ring }
        };
      });
      const contourGeo = {
        type: "FeatureCollection",
        features: contourFeatures
      };
      if (!this.map.getSource("contours-src")) {
        this.map.addSource("contours-src", {
          type: "geojson",
          data: contourGeo
        });
        this.map.addLayer({
          id: "contours-line",
          type: "line",
          source: "contours-src",
          paint: {
            "line-color": "rgba(148, 163, 184, 0.45)",
            "line-width": 1.2,
            "line-dasharray": [4, 3]
          }
        });
      } else {
        this.map.getSource("contours-src").setData(contourGeo);
      }
    }
