  function updateGISStatus(text) {
    const element = document.querySelector("#gisStatus");
    if (element) {
      element.textContent = text;
    }
  }
  function initMap() {
    const container = document.getElementById("gisMap");
    if (!container) return;
    try {
      map3 = new sm2({
        container: "gisMap",
        style: {
          version: 8,
          sources: {
            osm: {
              type: "raster",
              tiles: [
                OSM_TILE
              ],
              tileSize: 256,
              attribution: "\xA9 OpenStreetMap contributors"
            },
            satellite: {
              type: "raster",
              tiles: [
                SATELLITE_TILE
              ],
              tileSize: 256,
              attribution: "\xA9 Esri"
            },
            nasaLive: {
              type: "raster",
              tiles: [
                NASA_NRT_TILE
              ],
              tileSize: 256,
              attribution: "NASA GIBS"
            },
            terrain: {
              type: "raster-dem",
              tiles: [
                TERRAIN_TILE
              ],
              tileSize: 256,
              encoding: "terrarium",
              maxzoom: 15
            }
          },
          layers: [
            {
              id: "osm-base",
              type: "raster",
              source: "osm"
            }
          ],
          terrain: {
            source: "terrain",
            exaggeration: 1.3
          }
        },
        center: [
          79,
          22.8
        ],
        zoom: 4.4,
        pitch: 0,
        bearing: 0
      });
      map3.addControl(
        new lm2(),
        "top-right"
      );
      map3.on(
        "load",
        () => {
          updateGISStatus(
            "\u{1F525} MULTI-HAZARD HEATMAP ACTIVE \u2022 LANDSLIDES & FLASH FLOODS"
          );
          addSatelliteLayer();
          addLiveSatelliteLayer();
          addEarthquakeLayer();
          addLandslideLayer();
          addHeatmapLayers();
          addRoadNetworkLayer();
          addOverview3DHeatmapAndContours();
          setupOverviewCoordHUD();
          setupOverviewParticleSimulation();
          setupOverviewModeButtons();
          setMapMode("heatmap3d");
          loadNASAEvents();
          loadEarthquakes();
        }
      );
      map3.on(
        "error",
        (event) => {
          console.warn(
            "MapLibre error:",
            event
          );
        }
      );
    } catch (err) {
      console.warn("MapLibre init postponed until view is displayed:", err);
    }
  }
  function addSatelliteLayer() {
    if (map3.getLayer(
      "satellite-layer"
    )) {
      return;
    }
    map3.addLayer({
      id: "satellite-layer",
      type: "raster",
      source: "satellite",
      paint: {
        "raster-opacity": 1
      },
      layout: {
        visibility: "none"
      }
    });
  }
  function addLiveSatelliteLayer() {
    if (map3.getLayer(
      "nasa-live-layer"
    )) {
      return;
    }
    map3.addLayer({
      id: "nasa-live-layer",
      type: "raster",
      source: "nasaLive",
      paint: {
        "raster-opacity": 0.75
      },
      layout: {
        visibility: "none"
      }
    });
  }
  function addEarthquakeLayer() {
    if (!map3.getSource("earthquakes")) {
      map3.addSource("earthquakes", {
        type: "geojson",
        data: {
          type: "FeatureCollection",
          features: []
        }
      });
    }
    if (!map3.getLayer("earthquake-layer")) {
      map3.addLayer({
        id: "earthquake-layer",
        type: "circle",
        source: "earthquakes",
        paint: {
          "circle-radius": [
            "interpolate",
            ["linear"],
            ["coalesce", ["get", "mag"], 1],
            1,
            5,
            3,
            8,
            5,
            14,
            7,
            22
          ],
          "circle-color": "#d84c4c",
          "circle-opacity": 0.85,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 1.5
        }
      });
      map3.on("click", "earthquake-layer", (event) => {
        const properties = event.features[0].properties;
        const magnitude = properties.mag !== void 0 ? Number(properties.mag).toFixed(1) : "N/A";
        const time = properties.time ? new Date(Number(properties.time)).toLocaleString("en-IN") : "Unknown";
        new Bm2().setLngLat(event.lngLat).setHTML(`
          <strong>Earthquake</strong><br>
          Magnitude: ${magnitude}<br>
          Location: ${properties.place || "Unknown"}<br>
          Time: ${time}
        `).addTo(map3);
      });
    }
  }
  function addLandslideLayer() {
    if (!map3.getSource("landslides")) {
      map3.addSource("landslides", {
        type: "geojson",
        data: {
          type: "FeatureCollection",
          features: []
        }
      });
    }
    if (!map3.getLayer("landslide-layer")) {
      map3.addLayer({
        id: "landslide-layer",
        type: "circle",
        source: "landslides",
        paint: {
          "circle-radius": 5,
          "circle-color": "#e0a128",
          "circle-opacity": 0.85,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 1
        }
      });
      map3.on("click", "landslide-layer", (event) => {
        const properties = event.features[0].properties;
        new Bm2().setLngLat(event.lngLat).setHTML(`
          <strong>Historical Landslide</strong><br>
          ${properties.title || "NASA COOLR event"}<br>
          ${properties.date || "Date unavailable"}
        `).addTo(map3);
      });
    }
  }
