  window.zoomToHighway = function(id4) {
    const corridor = REGIONAL_HIGHWAY_CORRIDORS.find((c2) => c2.id === id4);
    if (!corridor || !map3) return;
    document.querySelector(".map-panel")?.scrollIntoView({ behavior: "smooth" });
    const roadLayers = ["highway-glow", "highway-casing", "highway-core", "highway-node-rings", "highway-node-cores"];
    roadLayers.forEach((layerId) => {
      if (map3.getLayer(layerId)) map3.setLayoutProperty(layerId, "visibility", "visible");
    });
    const chipRoads = document.getElementById("chipRoads");
    if (chipRoads) chipRoads.classList.add("active");
    map3.flyTo({
      center: corridor.center,
      zoom: 7.8,
      speed: 1.3,
      curve: 1.4,
      essential: true
    });
    setTimeout(() => {
      showHighwayPopup(corridor, corridor.center);
    }, 600);
    updateGISStatus(`\u{1F6E3}\uFE0F HIGHWAY CORRIDOR: ${corridor.highway} \u2022 STATUS: ${corridor.status}`);
  };
  function setupMapLayerChips() {
    const chipLandslides = document.getElementById("chipLandslides");
    const chipFloods = document.getElementById("chipFloods");
    const chipHotspots = document.getElementById("chipHotspots");
    const chipRoads = document.getElementById("chipRoads");
    if (chipLandslides) {
      chipLandslides.onclick = () => {
        chipLandslides.classList.toggle("active");
        updateHazardLayerFilter();
      };
    }
    if (chipFloods) {
      chipFloods.onclick = () => {
        chipFloods.classList.toggle("active");
        updateHazardLayerFilter();
      };
    }
    if (chipHotspots) {
      chipHotspots.onclick = () => {
        chipHotspots.classList.toggle("active");
        const isVisible = chipHotspots.classList.contains("active");
        if (map3.getLayer("hazard-hotspot-rings")) {
          map3.setLayoutProperty("hazard-hotspot-rings", "visibility", isVisible ? "visible" : "none");
          map3.setLayoutProperty("hazard-hotspot-core", "visibility", isVisible ? "visible" : "none");
        }
      };
    }
    if (chipRoads) {
      chipRoads.onclick = () => {
        chipRoads.classList.toggle("active");
        const isVisible = chipRoads.classList.contains("active");
        const roadLayers = ["highway-glow", "highway-casing", "highway-core", "highway-node-rings", "highway-node-cores"];
        roadLayers.forEach((layerId) => {
          if (map3.getLayer(layerId)) {
            map3.setLayoutProperty(layerId, "visibility", isVisible ? "visible" : "none");
          }
        });
      };
    }
  }
  function updateHazardLayerFilter() {
    const showLandslides = document.getElementById("chipLandslides")?.classList.contains("active");
    const showFloods = document.getElementById("chipFloods")?.classList.contains("active");
    let filter = "ALL";
    if (showLandslides && !showFloods) filter = "LANDSLIDE";
    else if (!showLandslides && showFloods) filter = "FLASH_FLOOD";
    else if (!showLandslides && !showFloods) filter = "NONE";
    const source = map3.getSource("hazard-heatmap-source");
    if (source) {
      source.setData(filter === "NONE" ? { type: "FeatureCollection", features: [] } : getHazardGeoJson(filter));
    }
  }
  var current3DFocusOrigin = [76.7843, 10.2147];
  var overviewParticleCtx = null;
  var overviewParticles = [];
  var overviewPhysicsRunning = false;
  var overviewAnimFrameId = null;
  function generateHypsometricHeatmapCanvas() {
    const SIZE = 1024;
    const canvas = document.createElement("canvas");
    canvas.width = SIZE;
    canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, SIZE, SIZE);
    const cx2 = SIZE / 2;
    const cy2 = SIZE / 2;
    const R3 = 460;
    const mainGrad = ctx.createRadialGradient(cx2, cy2, 0, cx2, cy2, R3);
    mainGrad.addColorStop(0, "rgba(200, 20, 20, 0.94)");
    mainGrad.addColorStop(0.06, "rgba(220, 38, 38, 0.90)");
    mainGrad.addColorStop(0.12, "rgba(239, 68, 40, 0.86)");
    mainGrad.addColorStop(0.2, "rgba(249, 115, 22, 0.80)");
    mainGrad.addColorStop(0.28, "rgba(251, 146, 60, 0.74)");
    mainGrad.addColorStop(0.36, "rgba(252, 211, 77, 0.68)");
    mainGrad.addColorStop(0.44, "rgba(250, 240, 55, 0.62)");
    mainGrad.addColorStop(0.52, "rgba(190, 235, 50, 0.55)");
    mainGrad.addColorStop(0.6, "rgba(74, 222, 128, 0.48)");
    mainGrad.addColorStop(0.68, "rgba(20, 184, 166, 0.40)");
    mainGrad.addColorStop(0.75, "rgba(6, 182, 212, 0.32)");
    mainGrad.addColorStop(0.83, "rgba(56, 189, 248, 0.22)");
    mainGrad.addColorStop(0.9, "rgba(59, 130, 246, 0.14)");
    mainGrad.addColorStop(0.96, "rgba(37, 99, 235, 0.06)");
    mainGrad.addColorStop(1, "rgba(0, 0, 0, 0.00)");
    ctx.save();
    ctx.scale(1, 0.82);
    ctx.beginPath();
    ctx.arc(cx2, cy2 / 0.82, R3, 0, Math.PI * 2);
    ctx.fillStyle = mainGrad;
    ctx.fill();
    ctx.restore();
    const rings = [
      { r: 28, lw: 2.2, color: "rgba(255, 255, 255, 0.80)" },
      { r: 52, lw: 1.8, color: "rgba(255, 220, 160, 0.75)" },
      { r: 78, lw: 1.8, color: "rgba(255, 200, 60, 0.70)" },
      { r: 105, lw: 1.6, color: "rgba(220, 240, 50, 0.65)" },
      { r: 132, lw: 1.6, color: "rgba(130, 235, 90, 0.60)" },
      { r: 160, lw: 1.4, color: "rgba(60, 220, 160, 0.54)" },
      { r: 188, lw: 1.4, color: "rgba(30, 200, 210, 0.48)" },
      { r: 215, lw: 1.2, color: "rgba(50, 190, 240, 0.40)" },
      { r: 242, lw: 1.2, color: "rgba(80, 170, 255, 0.32)" },
      { r: 268, lw: 1, color: "rgba(100, 150, 255, 0.24)" },
      { r: 294, lw: 1, color: "rgba(110, 130, 255, 0.18)" },
      { r: 320, lw: 0.8, color: "rgba(120, 120, 250, 0.12)" },
      { r: 346, lw: 0.8, color: "rgba(130, 110, 240, 0.08)" },
      { r: 372, lw: 0.6, color: "rgba(140, 100, 230, 0.05)" }
    ];
    ctx.save();
    ctx.scale(1, 0.82);
    rings.forEach((ring) => {
      ctx.beginPath();
      ctx.ellipse(cx2, cy2 / 0.82, ring.r, ring.r, 0, 0, Math.PI * 2);
      ctx.strokeStyle = ring.color;
      ctx.lineWidth = ring.lw;
      ctx.stroke();
    });
    ctx.restore();
    const coreGlow = ctx.createRadialGradient(cx2, cy2, 0, cx2, cy2, 40);
    coreGlow.addColorStop(0, "rgba(255, 255, 255, 0.35)");
    coreGlow.addColorStop(0.4, "rgba(255, 100, 50, 0.18)");
    coreGlow.addColorStop(1, "rgba(0, 0, 0, 0.00)");
    ctx.beginPath();
    ctx.arc(cx2, cy2, 40, 0, Math.PI * 2);
    ctx.fillStyle = coreGlow;
    ctx.fill();
    return canvas;
  }
  function addOverview3DHeatmapAndContours() {
    updateOverview3DHeatmapBounds(current3DFocusOrigin);
    updateOverviewContourLines(current3DFocusOrigin);
  }
  function updateOverview3DHeatmapBounds(origin = current3DFocusOrigin) {
    if (!map3) return;
    const [oLon, oLat] = origin;
    const spanLon = 0.09;
    const spanLat = 0.075;
    const bounds = [
      [oLon - spanLon / 2, oLat + spanLat / 2],
      [oLon + spanLon / 2, oLat + spanLat / 2],
      [oLon + spanLon / 2, oLat - spanLat / 2],
      [oLon - spanLon / 2, oLat - spanLat / 2]
    ];
    const canvas = generateHypsometricHeatmapCanvas();
    if (map3.getSource("heatmap-3d-raster-src")) {
      const src = map3.getSource("heatmap-3d-raster-src");
      src.updateImage({
        image: canvas,
        coordinates: bounds
      });
    } else {
      map3.addSource("heatmap-3d-raster-src", {
        type: "image",
        url: canvas.toDataURL(),
        coordinates: bounds
      });
      const src = map3.getSource("heatmap-3d-raster-src");
      if (src) {
        src.updateImage({
          image: canvas,
          coordinates: bounds
        });
      }
      map3.addLayer({
        id: "heatmap-3d-raster-layer",
        type: "raster",
        source: "heatmap-3d-raster-src",
        layout: { visibility: "none" },
        paint: {
          "raster-opacity": 0.88,
          "raster-fade-duration": 0
        }
      });
    }
    map3.triggerRepaint();
  }
  function updateOverviewContourLines(center = current3DFocusOrigin) {
    if (!map3) return;
    const [cLon, cLat] = center;
    const contourFeatures = [
      { elev: 1e3, r: 0.024, label: "1000 m" },
      { elev: 1200, r: 0.019, label: "1200 m" },
      { elev: 1400, r: 0.014, label: "1400 m" },
      { elev: 1600, r: 9e-3, label: "1600 m" },
      { elev: 1800, r: 4e-3, label: "1800 m" }
    ].map((item) => {
      const ring = [];
      const numPts = 32;
      for (let i2 = 0; i2 <= numPts; i2++) {
        const a2 = i2 / numPts * Math.PI * 2;
        const warp = 1 + 0.25 * Math.sin(a2 * 3) + 0.15 * Math.cos(a2 * 5);
        const lon = cLon + Math.cos(a2) * item.r * warp * 1.3;
        const lat = cLat + Math.sin(a2) * item.r * warp * 0.8;
        ring.push([lon, lat]);
      }
      return {
        type: "Feature",
        properties: { elevation: item.elev, label: item.label },
        geometry: { type: "LineString", coordinates: ring }
      };
    });
    const geo = {
      type: "FeatureCollection",
      features: contourFeatures
    };
    if (map3.getSource("contours-src")) {
      map3.getSource("contours-src").setData(geo);
    } else {
      map3.addSource("contours-src", {
        type: "geojson",
        data: geo
      });
      map3.addLayer({
        id: "contours-line",
        type: "line",
        source: "contours-src",
        layout: { visibility: "none" },
        paint: {
          "line-color": "rgba(148, 163, 184, 0.55)",
          "line-width": 1.4,
          "line-dasharray": [4, 3]
        }
      });
    }
  }
  function updateOverviewCollarCoordinates(center = current3DFocusOrigin) {
    const [cLon, cLat] = center;
    const latEl = document.getElementById("overviewCollarLat");
    const lonEl = document.getElementById("overviewCollarLon");
    const formatCoord = (val, dir) => {
      const deg = Math.floor(Math.abs(val));
      const min = Math.round((Math.abs(val) - deg) * 60).toString().padStart(2, "0");
      return `${deg}\xB0${min}' ${dir}`;
    };
    if (latEl) {
      latEl.innerHTML = `
      <span class="collar-tick">${formatCoord(cLat + 0.04, "N")}</span>
      <span class="collar-tick">${formatCoord(cLat + 0.015, "N")}</span>
      <span class="collar-tick">${formatCoord(cLat - 0.015, "N")}</span>
      <span class="collar-tick">${formatCoord(cLat - 0.04, "N")}</span>
    `;
    }
    if (lonEl) {
      lonEl.innerHTML = `
      <span class="collar-tick">${formatCoord(cLon - 0.05, "E")}</span>
      <span class="collar-tick">${formatCoord(cLon - 0.025, "E")}</span>
      <span class="collar-tick">${formatCoord(cLon, "E")}</span>
      <span class="collar-tick">${formatCoord(cLon + 0.025, "E")}</span>
      <span class="collar-tick">${formatCoord(cLon + 0.05, "E")}</span>
    `;
    }
  }
  function setupOverviewCoordHUD() {
    const hudEl = document.getElementById("overviewCoordHud");
    if (!hudEl || !map3) return;
    map3.on("mousemove", (e64) => {
      const lat = e64.lngLat.lat.toFixed(4);
      const lon = e64.lngLat.lng.toFixed(4);
      const elev = Math.round(1256 + 400 * Math.sin(e64.lngLat.lat * 100));
      hudEl.innerHTML = `Lat: <span class="coord-val">${lat}\xB0 N</span> &nbsp; Lon: <span class="coord-val">${lon}\xB0 E</span> &nbsp; Elev: <span class="coord-val">${elev.toLocaleString()} m</span>`;
    });
  }
  function setupOverviewParticleSimulation() {
    const canvas = document.getElementById("overviewParticleCanvas");
    if (!canvas || !map3) return;
    overviewParticleCtx = canvas.getContext("2d");
    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = rect.height;
    };
    resize();
    window.addEventListener("resize", resize);
    overviewParticles = [];
    for (let i2 = 0; i2 < 90; i2++) {
      overviewParticles.push({
        t: Math.random(),
        speed: 3e-3 + Math.random() * 5e-3,
        lateralSpread: (Math.random() - 0.5) * 28e-4,
        size: 1.5 + Math.random() * 3.5,
        color: Math.random() > 0.65 ? "#ef4444" : Math.random() > 0.3 ? "#f97316" : "#eab308",
        alpha: 0.6 + Math.random() * 0.4,
        trail: []
      });
    }
    const loop = () => {
      if (overviewPhysicsRunning && overviewParticleCtx && map3) {
        overviewParticleCtx.clearRect(0, 0, canvas.width, canvas.height);
        const origin = current3DFocusOrigin;
        const toe = [origin[0] + 0.015, origin[1] - 0.013];
        const originPix = map3.project(origin);
        const toePix = map3.project(toe);
        const dx2 = toePix.x - originPix.x;
        const dy2 = toePix.y - originPix.y;
        for (let i2 = 0; i2 < overviewParticles.length; i2++) {
          const p2 = overviewParticles[i2];
          p2.t += p2.speed;
          if (p2.t > 1) {
            p2.t = 0;
            p2.trail = [];
            continue;
          }
          const curX = originPix.x + dx2 * p2.t + p2.lateralSpread * canvas.width * Math.sin(p2.t * Math.PI);
          const curY = originPix.y + dy2 * p2.t + Math.pow(p2.t, 1.3) * 10;
          p2.trail.push({ x: curX, y: curY });
          if (p2.trail.length > 4) p2.trail.shift();
          if (p2.trail.length > 1) {
            overviewParticleCtx.beginPath();
            overviewParticleCtx.moveTo(p2.trail[0].x, p2.trail[0].y);
            for (let j3 = 1; j3 < p2.trail.length; j3++) {
              overviewParticleCtx.lineTo(p2.trail[j3].x, p2.trail[j3].y);
            }
            overviewParticleCtx.strokeStyle = p2.color;
            overviewParticleCtx.globalAlpha = p2.alpha * 0.45;
            overviewParticleCtx.lineWidth = p2.size * 0.8;
            overviewParticleCtx.stroke();
          }
          overviewParticleCtx.beginPath();
          overviewParticleCtx.arc(curX, curY, p2.size, 0, Math.PI * 2);
          overviewParticleCtx.fillStyle = p2.color;
          overviewParticleCtx.globalAlpha = p2.alpha;
          overviewParticleCtx.fill();
        }
      } else if (overviewParticleCtx) {
        overviewParticleCtx.clearRect(0, 0, canvas.width, canvas.height);
      }
      overviewAnimFrameId = requestAnimationFrame(loop);
    };
    if (overviewAnimFrameId) cancelAnimationFrame(overviewAnimFrameId);
    overviewAnimFrameId = requestAnimationFrame(loop);
  }
  function setupOverviewModeButtons() {
    document.querySelectorAll("#overviewViewmodePills .viewmode-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const mode = btn.dataset.overviewMode;
        setMapMode(mode);
      });
    });
    document.getElementById("overviewCompassWidget")?.addEventListener("click", () => {
      if (map3) map3.easeTo({ bearing: 0, duration: 600 });
    });
  }
  window.focusOverview3DHeatmap = function(lngLat, name) {
    if (Array.isArray(lngLat) && lngLat.length === 2) {
      current3DFocusOrigin = lngLat;
      setMapMode("heatmap3d");
    }
  };
  function setMapMode(mode) {
    if (!map3) return;
    const baseLayers = ["osm-base", "satellite-layer", "nasa-live-layer"];
    baseLayers.forEach((id4) => {
      if (map3.getLayer(id4)) map3.setLayoutProperty(id4, "visibility", "none");
    });
    if (map3.getLayer("osm-base")) {
      map3.setLayoutProperty("osm-base", "visibility", "visible");
    }
    const heatmapLayers = ["hazard-heat-glow", "hazard-hotspot-rings", "hazard-hotspot-core"];
    heatmapLayers.forEach((id4) => {
      if (map3.getLayer(id4)) map3.setLayoutProperty(id4, "visibility", "visible");
    });
    const roadLayers = ["highway-glow", "highway-casing", "highway-core", "highway-node-rings", "highway-node-cores"];
    roadLayers.forEach((id4) => {
      if (map3.getLayer(id4)) map3.setLayoutProperty(id4, "visibility", "visible");
    });
    document.querySelectorAll("#overviewViewmodePills .viewmode-btn").forEach((b2) => {
      const bMode = b2.dataset.overviewMode;
      const isAct = bMode === mode || mode === "2d" && bMode === "2d" || mode === "heatmap" && bMode === "2d";
      b2.classList.toggle("active", isAct);
    });
    if (mode === "heatmap3d") {
      if (map3.getLayer("satellite-layer")) {
        map3.setLayoutProperty("satellite-layer", "visibility", "visible");
        map3.setPaintProperty("satellite-layer", "raster-opacity", 1);
      }
      map3.setTerrain({ source: "terrain", exaggeration: 2.15 });
      updateOverview3DHeatmapBounds(current3DFocusOrigin);
      updateOverviewContourLines(current3DFocusOrigin);
      updateOverviewCollarCoordinates(current3DFocusOrigin);
      if (map3.getLayer("heatmap-3d-raster-layer")) {
        map3.setLayoutProperty("heatmap-3d-raster-layer", "visibility", "visible");
      }
      if (map3.getLayer("contours-line")) {
        map3.setLayoutProperty("contours-line", "visibility", "visible");
      }
      document.getElementById("overviewHeatmapLegend")?.classList.remove("hidden");
      document.getElementById("overviewCoordCollar")?.classList.remove("hidden");
      document.getElementById("overviewCompassWidget")?.classList.remove("hidden");
      document.getElementById("overviewScalebar")?.classList.remove("hidden");
      document.getElementById("overviewCoordHud")?.classList.remove("hidden");
      overviewPhysicsRunning = true;
      map3.easeTo({
        center: current3DFocusOrigin,
        zoom: 13.8,
        pitch: 65,
        bearing: -22,
        duration: 1200
      });
      updateGISStatus("\u{1F30B} 3D TOPOGRAPHIC HAZARD HEATMAP \u2022 FOS < 1.0 ACTIVE");
      return;
    }
    if (map3.getLayer("heatmap-3d-raster-layer")) {
      map3.setLayoutProperty("heatmap-3d-raster-layer", "visibility", "none");
    }
    document.getElementById("overviewHeatmapLegend")?.classList.add("hidden");
    document.getElementById("overviewCoordCollar")?.classList.add("hidden");
    overviewPhysicsRunning = false;
    if (mode === "terrain") {
      if (map3.getLayer("satellite-layer")) {
        map3.setLayoutProperty("satellite-layer", "visibility", "visible");
      }
      map3.setTerrain({ source: "terrain", exaggeration: 2 });
      updateOverviewContourLines(current3DFocusOrigin);
      if (map3.getLayer("contours-line")) {
        map3.setLayoutProperty("contours-line", "visibility", "visible");
      }
      document.getElementById("overviewCompassWidget")?.classList.remove("hidden");
      document.getElementById("overviewScalebar")?.classList.remove("hidden");
      document.getElementById("overviewCoordHud")?.classList.remove("hidden");
      map3.easeTo({ pitch: 58, bearing: -20, duration: 1e3 });
      updateGISStatus("\u26F0\uFE0F 3D TERRAIN \u2022 HAZARD ELEVATION RELIEF");
      return;
    }
    if (mode === "3d") {
      if (map3.getLayer("satellite-layer")) {
        map3.setLayoutProperty("satellite-layer", "visibility", "visible");
      }
      map3.setTerrain({ source: "terrain", exaggeration: 1.5 });
      if (map3.getLayer("contours-line")) {
        map3.setLayoutProperty("contours-line", "visibility", "none");
      }
      document.getElementById("overviewCompassWidget")?.classList.remove("hidden");
      document.getElementById("overviewScalebar")?.classList.remove("hidden");
      document.getElementById("overviewCoordHud")?.classList.remove("hidden");
      map3.easeTo({ pitch: 52, duration: 1e3 });
      updateGISStatus("\u26F0\uFE0F 3D SATELLITE PERSPECTIVE RELIEF");
      return;
    }
    map3.setTerrain(null);
    if (map3.getLayer("contours-line")) {
      map3.setLayoutProperty("contours-line", "visibility", "none");
    }
    if (mode === "2d" || mode === "heatmap" || mode === "risk") {
      updateHazardSourceFilter("ALL");
      updateGISStatus("\u{1F525} LIVE MULTI-HAZARD HEATMAP \u2022 LANDSLIDES & FLASH FLOODS");
      document.getElementById("chipLandslides")?.classList.add("active");
      document.getElementById("chipFloods")?.classList.add("active");
    }
    map3.easeTo({ pitch: 0, duration: 700 });
  }
  function updateHazardSourceFilter(filter) {
    const source = map3.getSource("hazard-heatmap-source");
    if (source) {
      source.setData(getHazardGeoJson(filter));
    }
  }
